  /**
   * Test {@link AbstractGetRDDHandler#addIterators(AccumuloStore, Configuration, User, Output)}.
   *
   * <ul>
   *   <li>Given {@link View} (default constructor).
   *   <li>Then calls {@link AccumuloStore#getSchema()}.
   * </ul>
   *
   * <p>Method under test: {@link AbstractGetRDDHandler#addIterators(AccumuloStore, Configuration,
   * User, Output)}
   */
  @Test
  @DisplayName(
      "Test addIterators(AccumuloStore, Configuration, User, Output); given View (default constructor); then calls getSchema()")
  @Tag("MaintainedByDiffblue")
  void testAddIterators_givenView_thenCallsGetSchema() throws OperationException, StoreException {
    // Arrange
    GetJavaRDDOfAllElementsHandler getJavaRDDOfAllElementsHandler =
        new GetJavaRDDOfAllElementsHandler();

    ByteEntityKeyPackage byteEntityKeyPackage = mock(ByteEntityKeyPackage.class);
    when(byteEntityKeyPackage.getIteratorFactory())
        .thenReturn(new ByteEntityIteratorSettingsFactory());

    Schema schema = mock(Schema.class);
    when(schema.getVisibilityProperty()).thenReturn("Visibility Property");
    when(schema.isAggregationEnabled()).thenReturn(true);

    AccumuloStore accumuloStore = mock(AccumuloStore.class);
    when(accumuloStore.getSchema()).thenReturn(schema);
    when(accumuloStore.getKeyPackage()).thenReturn(byteEntityKeyPackage);
    doNothing()
        .when(accumuloStore)
        .updateConfiguration(
            Mockito.<Configuration>any(), Mockito.<GraphFilters>any(), Mockito.<User>any());
    Configuration conf = new Configuration();
    User user = new User();

    GetJavaRDDOfAllElements getJavaRDDOfAllElements = new GetJavaRDDOfAllElements();
    getJavaRDDOfAllElements.setView(new View());

    // Act
    getJavaRDDOfAllElementsHandler.addIterators(accumuloStore, conf, user, getJavaRDDOfAllElements);

    // Assert
    verify(accumuloStore, atLeast(1)).getKeyPackage();
    verify(accumuloStore)
        .updateConfiguration(isA(Configuration.class), isA(GraphFilters.class), isA(User.class));
    verify(byteEntityKeyPackage, atLeast(1)).getIteratorFactory();
    verify(accumuloStore, atLeast(1)).getSchema();
    verify(schema, atLeast(1)).getVisibilityProperty();
    verify(schema, atLeast(1)).isAggregationEnabled();
    assertEquals(1447, conf.size());
  }

